            super().__init__()
            self.w1=t.nn.Parameter(w1.clone())
            self.b1=t.nn.Parameter(b1.clone())
            self.w2=t.nn.Parameter(w2.clone())
            self.b2=t.nn.Parameter(b2.clone())
        def forward(self,x):
            flat=x.reshape(x.shape[0],-1)
            h=(flat@self.w1.T+self.b1).clamp(min=0)
            y=h@self.w2.T+self.b2
