import torch as t
import einops

def solve(x,g,b,rm,rv,eps,momentum):
    mean=x.mean(dim=(0,2,3))
    var=((x-mean[None,:,None,None])**2).mean(dim=(0,2,3))
    z=(x-mean[None,:,None,None])/t.sqrt(var[None,:,None,None]+eps)
    y=z*g[None,:,None,None]+b[None,:,None,None]
    ym=y.mean(dim=(0,2,3))
    yv=((y-ym[None,:,None,None])**2).mean(dim=(0,2,3))
    return t.stack((ym,yv))

import torch as t
import einops

def solve(g,b,rm,rv,eps,momentum):
    class BatchNorm(t.nn.Module):
        def __init__(self):
            super().__init__()
            self.weight=t.nn.Parameter(g.clone())
            self.bias=t.nn.Parameter(b.clone())
            self.register_buffer("running_mean",rm.clone())
            self.register_buffer("running_var",rv.clone())
            self.register_buffer("num_batches_tracked",t.tensor(0))
        def forward(self,x):
            if self.training:
                mean=x.mean(dim=(0,2,3))
                var=((x-mean[None,:,None,None])**2).mean(dim=(0,2,3))
                with t.no_grad():
                    self.running_mean.copy_((1-momentum)*self.running_mean+momentum*mean)
                    self.running_var.copy_((1-momentum)*self.running_var+momentum*var)
                    self.num_batches_tracked += 1
            else:
                mean=self.running_mean
                var=self.running_var
            z=(x-mean[None,:,None,None])/t.sqrt(var[None,:,None,None]+eps)
            return z*self.weight[None,:,None,None]+self.bias[None,:,None,None]
    return BatchNorm()

