import torch as t

def solve(mods):
    class Sequential(t.nn.Module):
        def __init__(self):
            super().__init__()
            i=0
            for mod in mods:
                self.add_module(str(i),mod)
                i+=1
        def __len__(self):
            return len(self._modules)
        def __getitem__(self,i):
            return [self._modules[name] for name in self._modules][i]
        def forward(self,x):
            for name in self._modules:
                x=self._modules[name](x)
            return x
    return Sequential()

import torch as t

def solve(mods):
    class Counted(t.nn.Module):
        def __init__(self):
            super().__init__()
            i=0
            for mod in mods:
                self.add_module(str(i),mod)
                i+=1
            self.register_buffer("calls",t.tensor(0))
        def forward(self,x):
            self.calls+=1
            for name in self._modules:
                x=self._modules[name](x)
            return x
    return Counted()

