                self.right=t.nn.Sequential(t.nn.Conv2d(i,o,kernel_size=1,stride=s,bias=False),t.nn.BatchNorm2d(o))
            else:
                self.right=t.nn.Identity()
        def forward(self,x):
            return self.left(x)+self.right(x)
    return Block()

