        def __init__(self):
            super().__init__()
            self.in_layers=t.nn.Sequential(t.nn.Conv2d(cin,c0,kernel_size=7,stride=2,padding=3),t.nn.BatchNorm2d(c0),t.nn.ReLU(),t.nn.MaxPool2d(kernel_size=3,stride=2,padding=1))
