    return (t.cat([a, b]).tolist(), t.stack([a, b], dim=0).tolist())

import torch as t


def solve(x, k):
    """Overwrite the last k entries with a falling ramp, in place."""
    n = x.shape[0]
    t.linspace(1.0, 0.0, k, out=x[n - k:])
    return x.tolist()

import torch as t


def solve(z, k, s):
    """Fill the last k columns with s, then copy the first column over the last one."""
    z[:, -k:] = s
    z[:, -1].copy_(z[:, 0])
    return z.tolist()

