def solve(x):
    """Which rows already have unit length, and how many."""
    unit = t.abs(x.norm(dim=1) - 1.0) < 1e-6
    return (unit.tolist(), int(unit.sum().item()))

import torch as t


def solve(x):
    """Unit rows, with all-zero rows left as zero."""
    length = x.norm(dim=1, keepdim=True)
    safe = t.where(length > 0, length, t.ones_like(length))
    return (x / safe).tolist()

