def solve(x, ids):
    """Each row's requested value minus the mean of the other entries in that row."""
    picked = x[t.arange(x.shape[0]), ids]
    others = (x.sum(dim=1) - picked) / (x.shape[1] - 1)
    return (picked - others).tolist()

import torch as t


def solve(x, ids):
    """Two requested values per row, and their difference."""
    picked = x.gather(1, ids)
    return (picked.tolist(), (picked[:, 0] - picked[:, 1]).tolist())

