def solve(x,y):
    z=x-x.max(dim=1,keepdim=True)[0]
    p=z.exp()/z.exp().sum(dim=1,keepdim=True)
    member=(t.arange(x.shape[1]).reshape(1,-1)==y.reshape(-1,1))*1.
    return (p*member).sum(dim=1)

import torch as t

def solve(x):
    z=x-x.max(dim=1,keepdim=True)[0]
    l=z-z.exp().sum(dim=1,keepdim=True).log()
    return -(l.exp()*l).sum(dim=1)

import torch as t

def solve(x,y):
    own=(x*(t.arange(x.shape[1])[None,:]==y[:,None])).sum(dim=1,keepdim=True)
    better=(x>own).sum(dim=1)
    return (better<=1).to(t.float32).mean()

