import torch as t


def solve(model, u, x):
    """Output with every layer's output ablated."""
    def hook(layer, inputs, output):
        return output - (output @ u)[..., None] * u
    handles = []
    for layer in model:
        handles.append(layer.register_forward_hook(hook))
    out = model(x)
    for handle in handles:
        handle.remove()
    return out

