def solve(model, u, x):
    """Ablated output, model left untouched."""
    def hook(layer, inputs, output):
        return output - (output @ u)[..., None] * u
    handles = [model[0].register_forward_hook(hook), model[1].register_forward_hook(hook)]
    out = model(x)
    for handle in handles:
        handle.remove()
    return out

