def solve(H, B):
    """Average score of harmless rows after adding r."""
    r = H.mean(dim=0) - B.mean(dim=0)
    u = r / r.norm()
    return ((B + r) @ u).mean().item()

import torch as t


def solve(model, r, x, c):
    """Stacked outputs for the two insertion points."""
    def hook(layer, inputs, output):
        return output + c * r
    outs = []
    for k in [1, 0]:
        handle = model[k].register_forward_hook(hook)
        outs.append(model(x))
        handle.remove()
    return t.stack(outs)

import torch as t


def solve(model, u, r, x):
    """Stacked ablated and added outputs."""
    def ablate(layer, inputs, output):
        return output - (output @ u)[..., None] * u
    def add(layer, inputs, output):
        return output + r
    hs = [layer.register_forward_hook(ablate) for layer in model]
    first = model(x)
    for h in hs:
        h.remove()
    h = model[0].register_forward_hook(add)
    second = model(x)
    h.remove()
    return t.stack([first, second])

import torch as t


def solve(H, B, c):
    """Gap left after adding c times r."""
    r = H.mean(dim=0) - B.mean(dim=0)
    u = r / r.norm()
    return ((H @ u).mean() - ((B + c * r) @ u).mean()).item()

