def solve(table, base, gap):
    """Layers where ablation and addition both work."""
    down = base - table[:, 2] >= gap
    up = table[:, 4] >= gap
    return table[down & up][:, 0].tolist()

import torch as t


def solve(table, base, gap):
    """Layers that work but disturb harmless prompts."""
    down = base - table[:, 2] >= gap
    costly = table[:, 3] >= 0.1
    return table[down & costly][:, 0].tolist()

import torch as t


def solve(table, base, gap):
    """Cheapest layer that works both ways."""
    both = (base - table[:, 2] >= gap) & (table[:, 4] >= gap)
    if both.sum() == 0:
        return None
    kl = t.where(both, table[:, 3], t.tensor(float('inf')))
    return int(table[t.argmin(kl), 0].item())

import torch as t


def solve(table, thr):
    """First layer where ablation gets refusal to thr or lower."""
    ok = table[:, 2] <= thr
    if ok.sum() == 0:
        return None
    return int(table[ok][:, 0].min().item())

import torch as t


def solve(table, base, gap):
    """Number of layers that pass only the ablation half."""
    down = base - table[:, 2] >= gap
    up = table[:, 4] >= gap
    return (down.sum() - (down & up).sum()).item()

import torch as t


def solve(table, base):
    """Layers that work both ways beyond the noise."""
    g = 2 / 32
    both = (base - table[:, 2] > g) & (table[:, 4] > g)
    return table[both][:, 0].tolist()

import torch as t


def solve(table, L):
    """Layer chosen by the paper's rule, or None."""
    keep = (table[:, 0] < 0.8 * L) & (table[:, 3] < 0.1) & (table[:, 4] > 0)
    if keep.sum() == 0:
        return None
    score = t.where(keep, table[:, 2], t.tensor(2.0))
    tied = score == score.min()
    best = t.argmin(t.where(tied, table[:, 3], t.tensor(float('inf'))))
    return int(table[best, 0].item())

import torch as t


def solve(table, base, layer, c):
    """Short report for one layer, or None if not stored."""
    rows = table[table[:, 0] == layer]
    if rows.shape[0] == 0:
        return None
    row = rows[0]
    if c == 1:
        added = row[4].item()
    elif c == 2:
        added = row[5].item()
    else:
        return None
    return [(base - row[2]).item(), row[3].item(), added]
